import React, { useState } from 'react';
import {
  Modal, Box, Typography, Button, TextField, IconButton, Chip
} from '@mui/material';
import CloseIcon from '@mui/icons-material/Close';
import SearchableDropdown from '../FlowBuilder/Common/SearchableDropdown/SearchableDropdown.tsx'; 

interface SendEmailModalProps {
  open: boolean;
  onClose: () => void;
  onSend: (selectedType: string, emails: string[], isTest: boolean) => void;
  campaignName?: string;
}

const emailTypes = [
  { value: 'recce', label: 'Recce Email' },
  { value: 'pipelineOfSupplier', label: 'Pipelined Societies Email' },
  { value: 'listOfSupplier', label: 'Booking (Upcoming Society Activation Email)' },
  { value: 'activationOfSupplier', label: 'Activation of Society, Branding and Permission Email' },
  { value: 'prehype', label: 'Prehype Email' }
];

const SendEmailModal: React.FC<SendEmailModalProps> = ({
  open,
  onClose,
  onSend,
  campaignName
}) => {
  const [emailType, setEmailType] = useState<string>('');
  const [emails, setEmails] = useState<string[]>([]);

  const handleSend = (isTest: boolean) => {
    if (!emailType) return;
    onSend(emailType, emails, isTest);
  };

  return (
    <Modal open={open} onClose={onClose}>
      <Box sx={{
        position: 'absolute',
        top: '50%',
        left: '50%',
        transform: 'translate(-50%, -50%)',
        bgcolor: 'background.paper',
        boxShadow: 24,
        borderRadius: 2,
        p: 4,
        width: 500,
        maxHeight: '90vh',
        overflowY: 'auto',
      }}>
        <Box display="flex" justifyContent="space-between" alignItems="center" mb={2}>
          <Typography variant="h6" fontWeight="bold">
            Send Emails for {campaignName || 'Campaign'}
          </Typography>
          <IconButton size="small" onClick={onClose}><CloseIcon /></IconButton>
        </Box>

        {/* ✅ SearchableDropdown instead of <Select> */}
        <Typography variant="body1" gutterBottom>Select Email Type:</Typography>
        <SearchableDropdown
          label="Email Type"
          value={emailTypes.find((item) => item.value === emailType) || null}
          onChange={(selected) => setEmailType(selected?.value || '')}
          options={emailTypes}
          valueKey="value"
          labelKey="label"
          error={!emailType}
          errorMessage="Please select an email type"
        />

        <Typography variant="body1" mt={2} gutterBottom>
          Enter email addresses (comma separated):
        </Typography>
        <TextField
          fullWidth
          multiline
          placeholder="Enter emails separated by commas"
          value={emails.join(', ')}
          onChange={(e) => {
            const input = e.target.value;
            const parts = input.split(',').map(e => e.trim()).filter(e => e);
            setEmails(parts);
          }}
        />

        <Box mt={2}>
          {emails.map((email, idx) => (
            <Chip
              key={idx}
              label={email}
              onDelete={() => setEmails(prev => prev.filter((_, i) => i !== idx))}
              sx={{ m: 0.5 }}
            />
          ))}
        </Box>

        <Typography variant="caption" color="textSecondary" mt={2} display="block">
          Note: Use comma-separated emails to send to multiple users at once.
        </Typography>

        <Box mt={4} display="flex" justifyContent="space-between" flexWrap="wrap" gap={1}>
          <Button
             variant="contained"
            color="primary"
         size="small"
            onClick={() => handleSend(true)}
            disabled={!emailType || emails.length === 0}
          >
            Send Email For Given User
          </Button>
          <Button
           variant="contained"
           color="primary"
           size="small"
            onClick={() => handleSend(false)}
            disabled={!emailType}
          >
            Send to All (Default)
          </Button>
        </Box>
      </Box>
    </Modal>
  );
};

export default SendEmailModal;
